changeSet.sql:
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'hugmesh_register_sql') THEN
    -- NOLOGIN: never a connection identity, only a SET ROLE target.
    -- NOSUPERUSER / NOCREATEDB / NOCREATEROLE / NOINHERIT: no escalation,
    -- and crucially no COPY ... TO PROGRAM (superuser-only) host RCE.
    CREATE ROLE hugmesh_register_sql
      NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS;
  END IF;
END $$;

DO $$
DECLARE
  t   text;
  seq text;
  catalog_tables text[] := ARRAY[
    'games','levels','chapters',
    'federation_modules','game_access','game_event_support'
  ];
  col text;
BEGIN
  -- Strip any privileges a prior run / default may have granted broadly,
  -- then grant ONLY what register.sql needs on ONLY the six catalog
  -- tables: SELECT (for INSERT ... SELECT FROM games) + INSERT + UPDATE
  -- (ON CONFLICT DO UPDATE upserts). No DELETE, no TRUNCATE, no
  -- references, and nothing at all on any other table.
  FOREACH t IN ARRAY catalog_tables LOOP
    IF EXISTS (
      SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relname = t AND c.relkind = 'r'
    ) THEN
      EXECUTE format('GRANT SELECT, INSERT, UPDATE ON public.%I TO hugmesh_register_sql', t);
      -- Owned (serial/identity) sequences need USAGE+SELECT for nextval.
      FOR seq IN
        SELECT s.relname
        FROM pg_depend d
        JOIN pg_class s ON s.oid = d.objid AND s.relkind = 'S'
        JOIN pg_class r ON r.oid = d.refobjid
        JOIN pg_namespace n ON n.oid = r.relnamespace
        WHERE n.nspname = 'public' AND r.relname = t
      LOOP
        EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE public.%I TO hugmesh_register_sql', seq);
      END LOOP;
    END IF;
  END LOOP;
END $$;

DO $$
DECLARE
  override_role text := nullif('${app.register-sql.login-role}', '');
  login_role    text := coalesce(override_role, current_user);
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = login_role) THEN
    EXECUTE format('GRANT hugmesh_register_sql TO %I', login_role);
  END IF;
END $$;
